 ["dashboard","لوحة التحكم","⌂"],["homepage","إعدادات الشاشة الرئيسية","✦"],["my-account","حسابي","◉"],["students","الطلاب","♥"],["parents","أولياء الأمور","♧"],["teachers","المعلمون","♦"],["employees","الموظفون","♙"],["classes","الفصول والشُعب","▣"],["subjects","المواد الدراسية","◆"],["shifts","الفترات وأيام العمل","☼"],["relations","الربط والتسكين","⌘"],["accounts","ربط الحسابات","♚"],["credentials","دخول الطلاب والأهالي","●"],["staff-access","دخول المعلمين والإدارة","♜"],["content","الواجبات والإعلانات","✦"],["attendance","الحضور والغياب","✓"],["schedule","الجدول الدراسي","◷"],["grades","الدرجات والشهادات","★"],["fees","المصروفات","◈"],["reports","التقارير","≡"],["users","المستخدمون والصلاحيات","♚"],["settings","إعدادات المدرسة","⚙"]
