function RecordsView({type,label,notify}:{type:"students"|"parents"|"teachers"|"employees"|"classes";label:string;notify:(s:string)=>void}){
 const [items,setItems]=useState<DbRow[]>([]),[q,setQ]=useState(""),[loading,setLoading]=useState(true),[editing,setEditing]=useState<DbRow|null>(null),[open,setOpen]=useState(false),[form,setForm]=useState({name:"",detail:"",meta:"",capacity:"30"}),[error,setError]=useState(""),[shiftName,setShiftName]=useState("");
 const load=()=>{setLoading(true);fetch(`/api/records?type=${type}&q=${encodeURIComponent(q)}`).then(r=>r.json()).then(d=>{if(d.items)setItems(d.items);else setError(d.error||"تعذر التحميل")}).finally(()=>setLoading(false))};useEffect(()=>{load()},[type,q]);
 useEffect(()=>{if(type!=="classes")return;fetch("/api/session/shifts").then(r=>r.ok?r.json():null).then(d=>{const current=d?.shifts?.find((s:{id:number;name:string})=>s.id===d.activeShiftId);setShiftName(current?.name||"")})},[type]);
 const labels=type==="students"?["اسم الطالب","الصف والفصل","رقم الطالب"]:type==="parents"?["اسم ولي الأمر","رقم الهاتف","رقم ولي الأمر"]:type==="teachers"?["اسم المعلم","التخصص","رقم الموظف"]:type==="employees"?["اسم الموظف","المسمى الوظيفي","رقم الموظف"]:["اسم الصف والشعبة","المرحلة أو الصف الدراسي","رمز الفصل"];
 const show=(row?:DbRow)=>{setEditing(row??null);setForm(row?{name:row.name,detail:row.detail,meta:row.meta,capacity:String(row.capacity??30)}:{name:"",detail:"",meta:"",capacity:"30"});setError("");setOpen(true)};
 const save=async(e:React.FormEvent)=>{e.preventDefault();setError("");const r=await fetch(`/api/records?type=${type}`,{method:editing?"PUT":"POST",headers:{"content-type":"application/json"},body:JSON.stringify({...form,id:editing?.id})}),d=await r.json();if(!r.ok){setError(d.error||"تعذر الحفظ");return}setOpen(false);notify(d.message);load()};
 const archive=async(row:DbRow)=>{if(!confirm(`أرشفة ${row.name}؟ يمكن استعادة السجل لاحقًا.`))return;const r=await fetch(`/api/records?type=${type}&id=${row.id}`,{method:"DELETE"}),d=await r.json();if(r.ok){notify(d.message);load()}else setError(d.error)};
 return <>{type==="classes"&&<section className="class-registration-card"><span>تسجيل الفصول والشُعب</span><h2>{shiftName||"الفترة الحالية"}</h2><p>كل فصل تضيفه هنا يُسجّل تلقائيًا ضمن هذه الفترة فقط.</p></section>}<div className="toolbar"><div className="search">⌕<input value={q} onChange={e=>setQ(e.target.value)} placeholder={`ابحث في ${label}...`}/></div><button className="primary" onClick={()=>show()}>+ إضافة جديد</button></div>{error&&<div className="form-error">{error}</div>}<div className="panel table-wrap"><table><thead><tr><th>الاسم</th><th>التفاصيل</th><th>الحالة</th><th>المعرف</th><th>الإجراءات</th></tr></thead><tbody>{items.map(r=><tr key={r.id}><td><span className="mini-avatar">{r.name[0]}</span><strong>{r.name}</strong></td><td>{r.detail}</td><td><span className="badge">{r.status==="ACTIVE"?"نشط":r.status}</span></td><td>{r.meta}</td><td><div className="row-actions"><button onClick={()=>show(r)}>تعديل</button><button className="danger" onClick={()=>archive(r)}>أرشفة</button></div></td></tr>)}</tbody></table>{loading&&<div className="empty">جارٍ تحميل البيانات...</div>}{!loading&&!items.length&&<div className="empty">لا توجد سجلات</div>}</div>{open&&<div className="modal-backdrop" onMouseDown={()=>setOpen(false)}><form className="modal" onSubmit={save} onMouseDown={e=>e.stopPropagation()}><button type="button" className="close" onClick={()=>setOpen(false)}>×</button><h2>{editing?"تعديل السجل":type==="classes"?"تسجيل فصل أو شعبة جديدة":"إضافة سجل جديد"}</h2>{type==="classes"&&<div className="class-form-note">سيُسجّل في: <strong>{shiftName||"الفترة الحالية"}</strong></div>}{error&&<div className="form-error">{error}</div>}<label>{labels[0]}<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder={type==="classes"?"مثال: الصف السادس (أ)":""}/></label><label>{labels[1]}<input value={form.detail} onChange={e=>setForm({...form,detail:e.target.value})} placeholder={type==="classes"?"مثال: المرحلة الأساسية — الصف السادس":""}/></label><label>{labels[2]}<input value={form.meta} disabled={!!editing} onChange={e=>setForm({...form,meta:e.target.value})} placeholder={type==="classes"?"مثال: 6-A":""}/></label>{type==="classes"&&<label>السعة الطلابية<input type="number" min="1" value={form.capacity} onChange={e=>setForm({...form,capacity:e.target.value})}/></label>}<button className="primary" type="submit">{editing?"حفظ التعديل":type==="classes"?"تسجيل الفصل في الفترة":"إضافة السجل"}</button></form></div>}</>
}
function UsersManager({notify}:{notify:(s:string)=>void}){
 const [users,setUsers]=useState<Array<{id:number;email:string;full_name:string;role:string;status:string}>>([]),[open,setOpen]=useState(false),[error,setError]=useState(""),[form,setForm]=useState({fullName:"",email:"",role:"TEACHER"});
 const load=()=>fetch("/api/users").then(r=>r.json()).then(d=>d.users?setUsers(d.users):setError(d.error));useEffect(()=>{load()},[]);
 const add=async(e:React.FormEvent)=>{e.preventDefault();const r=await fetch("/api/users",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(form)}),d=await r.json();if(!r.ok){setError(d.error);return}setOpen(false);notify(d.message);load()};
 const update=async(id:number,role:string,status:string)=>{const r=await fetch("/api/users",{method:"PUT",headers:{"content-type":"application/json"},body:JSON.stringify({id,role,status})}),d=await r.json();if(r.ok){notify(d.message);load()}else setError(d.error)};
 const roleName:Record<string,string>={SUPER_ADMIN:"مدير النظام",ADMIN:"مدير المدرسة",TEACHER:"معلم",STUDENT:"طالب",PARENT:"ولي أمر",EMPLOYEE:"موظف"};
 return <><div className="settings-intro"><div><h2>المستخدمون والصلاحيات</h2><p>إضافة الحسابات وتحديد دور كل مستخدم وتعطيله عند الحاجة.</p></div><button className="primary" onClick={()=>setOpen(true)}>+ إضافة مستخدم</button></div>{error&&<div className="form-error">{error}</div>}<div className="panel table-wrap"><table><thead><tr><th>المستخدم</th><th>البريد</th><th>الدور</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody>{users.map(u=><tr key={u.id}><td><strong>{u.full_name}</strong></td><td>{u.email}</td><td><select value={u.role} onChange={e=>update(u.id,e.target.value,u.status)}>{Object.entries(roleName).map(([v,n])=><option value={v} key={v}>{n}</option>)}</select></td><td><span className="badge">{u.status==="ACTIVE"?"نشط":"موقوف"}</span></td><td><button className={u.status==="ACTIVE"?"danger-link":"action-link"} onClick={()=>update(u.id,u.role,u.status==="ACTIVE"?"SUSPENDED":"ACTIVE")}>{u.status==="ACTIVE"?"تعطيل":"تفعيل"}</button></td></tr>)}</tbody></table></div>{open&&<div className="modal-backdrop" onMouseDown={()=>setOpen(false)}><form className="modal" onSubmit={add} onMouseDown={e=>e.stopPropagation()}><button type="button" className="close" onClick={()=>setOpen(false)}>×</button><h2>إضافة مستخدم</h2><label>الاسم الكامل<input value={form.fullName} onChange={e=>setForm({...form,fullName:e.target.value})}/></label><label>البريد الإلكتروني<input type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></label><label>الدور<select value={form.role} onChange={e=>setForm({...form,role:e.target.value})}>{Object.entries(roleName).filter(([v])=>v!=="SUPER_ADMIN").map(([v,n])=><option value={v} key={v}>{n}</option>)}</select></label><button className="primary" type="submit">إضافة المستخدم</button></form></div>}</>
}

